#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define N 9
#define DISK_MAX 199        /* 磁盘最大柱面号：SCAN/C-SCAN 要扫到这里，LOOK 不必 */
static int req[N] = {55, 58, 39, 18, 90, 160, 150, 38, 184};
static int start = 100;

static int cmp(const void *a, const void *b) { return *(const int *)a - *(const int *)b; }

int fcfs(void) {
    int cur = start, t = 0;
    for (int i = 0; i < N; i++) { t += abs(req[i] - cur); cur = req[i]; }
    return t;
}
int sstf(void) {
    int done[N] = {0}, cur = start, t = 0;
    for (int k = 0; k < N; k++) {
        int best = -1, bd = INT_MAX;
        for (int i = 0; i < N; i++)
            if (!done[i] && abs(req[i] - cur) < bd) { bd = abs(req[i] - cur); best = i; }
        t += bd; cur = req[best]; done[best] = 1;
    }
    return t;
}
/* SCAN：向外扫到磁盘端点 DISK_MAX，再折返服务剩下的请求 */
int scan(void) {
    int s[N]; for (int i = 0; i < N; i++) s[i] = req[i];
    qsort(s, N, sizeof(int), cmp);
    int split = 0;
    while (split < N && s[split] < start) split++;
    int t = DISK_MAX - start;                 /* 从 start 一路开到端点 */
    for (int i = split - 1; i >= 0; i--) t += (i == split - 1 ? DISK_MAX - s[i] : s[i + 1] - s[i]);
    return t;
}
/* LOOK：只扫到最后一个请求就折返，省掉「到端点」的无效行程 */
int look(void) {
    int s[N]; for (int i = 0; i < N; i++) s[i] = req[i];
    qsort(s, N, sizeof(int), cmp);
    int split = 0;
    while (split < N && s[split] < start) split++;
    int cur = start, t = 0;
    for (int i = split; i < N; i++) { t += abs(s[i] - cur); cur = s[i]; }
    for (int i = split - 1; i >= 0; i--) { t += abs(s[i] - cur); cur = s[i]; }
    return t;
}
/* C-SCAN：只对外服务，到端点后直接跳回 0（回程不服务），再从 0 往外服务 */
int cscan(void) {
    int s[N]; for (int i = 0; i < N; i++) s[i] = req[i];
    qsort(s, N, sizeof(int), cmp);
    int split = 0;
    while (split < N && s[split] < start) split++;
    int t = DISK_MAX - start;                 /* 向外到端点 */
    t += DISK_MAX;                            /* 回程：端点 -> 0，不服务 */
    if (split > 0) t += s[split - 1];         /* 从 0 往外到最高的小于 start 的请求 */
    return t;
}
/* C-LOOK：同 C-SCAN，但只到最后一个请求，回程跳到最小的请求 */
int clook(void) {
    int s[N]; for (int i = 0; i < N; i++) s[i] = req[i];
    qsort(s, N, sizeof(int), cmp);
    int split = 0;
    while (split < N && s[split] < start) split++;
    int cur = start, t = 0;
    for (int i = split; i < N; i++) { t += abs(s[i] - cur); cur = s[i]; }
    if (split > 0) {
        t += abs(cur - s[0]);                 /* 回程跳到最小请求 */
        cur = s[0];
        for (int i = 1; i < split; i++) { t += abs(s[i] - cur); cur = s[i]; }
    }
    return t;
}

int main(void) {
    printf("start head = %d, disk cylinders = 0..%d\n", start, DISK_MAX);
    printf("requests   = 55, 58, 39, 18, 90, 160, 150, 38, 184\n");
    printf("FCFS   = %d\n", fcfs());
    printf("SSTF   = %d\n", sstf());
    printf("SCAN   = %d  (sweeps to disk end %d)\n", scan(), DISK_MAX);
    printf("LOOK   = %d  (turns at the last request)\n", look());
    printf("C-SCAN = %d  (return trip not served)\n", cscan());
    printf("C-LOOK = %d\n", clook());
    printf("LOOK saves SCAN's pointless trip to the disk end: %d < %d\n", look(), scan());
    printf("SSTF is shortest but starves far requests; C-SCAN equalizes wait time\n");
    return 0;
}
